// ─── Validação de Sessão ────────────────────────────────────────────────
// Garante que o payload contém os campos mínimos obrigatórios.
// A FSM continua sendo a fonte da verdade — N8N NÃO controla estados.

const body = $input.item.json.body || $input.item.json;

const evento = body.evento;
const protocolo = body.protocolo;
const cliente = body.cliente;
const juridico = body.juridico;

// Validações mínimas
const errors = [];

if (!evento) errors.push('evento ausente');
if (!protocolo) errors.push('protocolo ausente');
if (!cliente?.nome) errors.push('cliente.nome ausente');
if (!juridico?.area) errors.push('juridico.area ausente');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      errors,
      protocolo: protocolo || null
    }
  }];
}

// Extrair sessionId do protocolo (JUR-YYYYMMDD-XXXX)
const sessionId = `session_${protocolo.replace(/[^A-Z0-9]/gi, '_')}`;

return [{
  json: {
    valid: true,
    evento,
    protocolo,
    sessionId,
    cliente,
    juridico,
    documentos: body.documentos || [],
    hermes: body.hermes || null,
    timestamp: body.timestamp || new Date().toISOString()
  }
}];

// ─── Recuperar / Construir Contexto da Sessão ──────────────────────────
// N8N NÃO armazena estado da conversa — constrói contexto a partir
// dos dados recebidos no payload (fonte única de verdade).

const data = $json;

// Contexto enriquecido para processamento
const contexto = {
  sessao: {
    id: data.sessionId,
    protocolo: data.protocolo,
    evento: data.evento,
    timestamp: data.timestamp
  },
  cliente: {
    nome: data.cliente.nome,
    telefone: data.cliente.telefone,
    email: data.cliente.email,
    cidade: data.cliente.cidade,
    estado: data.cliente.estado
  },
  juridico: {
    area: data.juridico.area,
    subarea: data.juridico.subarea,
    descricao_caso: data.juridico.descricao_caso || data.juridico.descricaoCaso || ''
  },
  documentos: data.documentos || [],
  hermes: data.hermes || null,
  // Flags de processamento
  qualificacaoCompleta: true, // Webhook só dispara após qualificação completa
  temDocumentos: (data.documentos || []).length > 0,
  temHermes: !!data.hermes && data.hermes.status === 'concluida'
};

return [{ json: contexto }];

// ─── Memória Conversacional — Previdenciário ────────────────────────────
// Constrói contexto jurídico especializado para a área previdenciária.
// Identifica subárea e prepara perguntas de qualificação específicas.

const ctx = $json;
const subarea = ctx.juridico.subarea;
const descricao = ctx.juridico.descricao_caso;

// Mapeamento de perguntas por subárea
const perguntasPorSubarea = {
  'BPC/LOAS': [
    'Qual é a renda familiar mensal total?',
    'Há membros com deficiência grave na família?',
    'Já houve negativa do INSS anteriormente?',
    'Qual a data de nascimento do requerente?'
  ],
  'Aposentadoria': [
    'Qual o tempo de contribuição até o momento?',
    'Qual categoria de segurado (empregado, autônomo, rural)?',
    'Há períodos de atividade especial (insalubres/periculosos)?',
    'Possui CTPS ou carnês de contribuição?\''
  ],
  'Auxílio-doença': [
    'Qual o CID da doença diagnosticada?',
    'Qual a data de início da incapacidade?',
    'Já solicitou auxílio ao INSS? Qual o resultado?',
    'Há atestados médicos recentes (menos de 30 dias)?'
  ],
  'Pensão': [
    'Qual o grau de parentesco com o falecido?',
    'O falecido era contribuinte ativo ou aposentado?',
    'Há outros dependentes que já recebem pensão?',
    'Qual a data do óbito?'
  ],
  'Revisão': [
    'Qual benefício está em revisão (número NB)?',
    'Qual o motivo da revisão (erro de cálculo, tempo especial, etc.)?',
    'Qual a data de concessão do benefício original?',
    'Há decisão administrativa anterior?'
  ]
};

const perguntas = perguntasPorSubarea[subarea] || [
  'Descreva melhor a situação previdenciária.',
  'Há documentação de histórico de contribuição disponível?'
];

return [{
  json: {
    ...ctx,
    area_config: {
      area: 'Previdenciário',
      subarea,
      perguntas_qualificacao: perguntas,
      documentos_necessarios: [
        'RG e CPF',
        'CTPS ou Carnê de contribuição',
        'Extrato do CNIS (disponível no Meu INSS)',
        'Laudos e atestados médicos (se aplicável)'
      ],
      urgencia_padrao: subarea === 'Auxílio-doença' ? 'alta' : 'media',
      complexidade_padrao: ['Revisão', 'Aposentadoria'].includes(subarea) ? 'alta' : 'media'
    }
  }
}];

