}

return [{
  json: {
    ...ctx,
    n8n_analysis: {
      area: 'Cível',
      subarea_confirmada: aiAnalysis.subarea_confirmada || ctx.juridico.subarea,
      urgencia: aiAnalysis.urgencia || ctx.area_config.urgencia_padrao,
      complexidade: aiAnalysis.complexidade || ctx.area_config.complexidade_padrao,
