      documentos_essenciais: aiAnalysis.documentos_essenciais || ctx.area_config.documentos_necessarios,
      resumo_executivo: aiAnalysis.resumo_executivo || '',
      recomendacao_acao: aiAnalysis.recomendacao_acao || '',
      processado_em: new Date().toISOString()
    }
  }
}];

// ─── Gerador de Resumo Executivo Final ──────────────────────────────────
// Consolida todos os dados do contexto + análise OpenAI em um resumo
// estruturado pronto para envio à equipe jurídica.

const ctx = $json;
const analysis = ctx.n8n_analysis;
const cliente = ctx.cliente;
const juridico = ctx.juridico;
const hermes = ctx.hermes;

// Prioridade: Hermes (Sprint 3.5) > N8N OpenAI > Padrão da área
const urgenciaFinal = hermes?.urgencia || analysis.urgencia || 'media';
const complexidadeFinal = hermes?.complexidade || analysis.complexidade || 'media';

// Resumo executivo consolidado
const resumo = {
  protocolo: ctx.protocolo,
  processado_em: new Date().toISOString(),

  cliente: {
    nome: cliente.nome,
    telefone: cliente.telefone,
    email: cliente.email,
    localizacao: `${cliente.cidade}/${cliente.estado}`
  },

  caso: {
    area: analysis.area,
    subarea: analysis.subarea_confirmada || juridico.subarea,
    descricao: juridico.descricao_caso
  },

  classificacao: {
    urgencia: urgenciaFinal,
    complexidade: complexidadeFinal,
    urgencia_badge: urgenciaFinal === 'alta' ? '🔴 URGENTE' : urgenciaFinal === 'media' ? '🟡 MÉDIO' : '🟢 BAIXO',
    complexidade_badge: complexidadeFinal === 'alta' ? '⚠️ COMPLEXO' : '✅ PADRÃO'
  },

  analise_n8n: {
    resumo_executivo: analysis.resumo_executivo,
    recomendacao_acao: analysis.recomendacao_acao,
    perguntas_adicionais: analysis.perguntas_adicionais
  },

  hermes_analysis: hermes ? {
    urgencia: hermes.urgencia,
    complexidade: hermes.complexidade,
    resumo: hermes.resumo,
    status: hermes.status
  } : null,

  documentos: {
    count: ctx.documentos.length,
    arquivos: ctx.documentos.map(d => ({
      nome: d.original_name || d.nome || d.fileName,
      tipo: d.mime_type || d.tipo,
      tamanho: d.size_bytes || d.tamanho
    })),
    documentos_solicitados: analysis.documentos_essenciais
  },

  // Placeholder para integrações futuras (Sprint 4.1 — Kinbox)
  encaminhamento: {
    destino: 'equipe_juridica',
    canal: 'webhook_interno',
    status: 'pendente'
  }
};

return [{ json: { resumo, contexto_original: ctx } }];

// ─── Encerramento do Workflow ────────────────────────────────────────────
// Prepara a resposta final para o chamador do webhook e
// sinaliza que o atendimento foi processado com sucesso.
// 
// Integrações futuras (Sprint 4.1):
//   - Kinbox: enviar resumo ao atendente
//   - Email: notificar advogado responsável
//   - CRM: registrar lead qualificado

const { resumo, contexto_original } = $json;

return [{
  json: {
    sucesso: true,
    protocolo: resumo.protocolo,
    processado_em: resumo.processado_em,
    area: resumo.caso.area,
    subarea: resumo.caso.subarea,
    urgencia: resumo.classificacao.urgencia,
    complexidade: resumo.classificacao.complexidade,
    resumo_executivo: resumo.analise_n8n.resumo_executivo,
    documentos_solicitados: resumo.documentos.documentos_solicitados,
    perguntas_adicionais: resumo.analise_n8n.perguntas_adicionais,
    // Metadados do processamento
    _meta: {
      workflow: 'chat-juridico-orchestration-v1.0',
      sprint: '4.0',
      fontes_analise: [
        contexto_original.temHermes ? 'hermes' : null,
        'n8n-openai'
      ].filter(Boolean)
    }
  }
}];

const area = $json.juridico?.area || 'desconhecida';
return [{
  json: {
    sucesso: false,
    erro: `Área jurídica não mapeada: ${area}`,
    area_recebida: area,
    areas_suportadas: ['Previdenciário', 'Trabalhista', 'Tributário', 'Cível']
  }
}];
